import os, glob, re

def load_grids():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t_path = d+'/../../sessions/'+os.path.basename(d)+'.jsonl'
    try:
        t = open(t_path).read().replace('\\n','\n')
    except:
        return {}
    G = {}
    pattern = re.compile(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):')
    for m in pattern.finditer(t):
        k, h, w = m[1], int(m[2]), int(m[3])
        match_start = m.end()
        rows = []
        for i in range(h):
            line_start = t.find('\n', t.find('\n', match_start - 10)) + 1
            line_end = t.find('\n', line_start)
            row_str = t[match_start:line_end].strip()
            if all(x.isdigit() for x in row_str.split()):
                rows.append([int(x) for x in row_str.split()])
        if rows and k not in G:
            G[k] = rows
    return G

